import Cart from "./cart.js";
import { parseCents, formatCents, CURRENCY } from "./money.js";
import * as readline from "readline";

const cart = new Cart();
const rl = readline.createInterface({ input: process.stdin });
for await (const line of rl) {
  const [command, name, price, qty] = line.trim().split(/\s+/);
  try {
    if (command === "add") {
      cart.add(name, parseCents(price), Number(qty ?? 1));
      console.log(`added ${name}`);
    } else if (command === "remove") {
      console.log(cart.remove(name) ? `removed ${name}` : `no ${name}`);
    } else if (command === "total") {
      console.log(`total ${formatCents(cart.total)} ${CURRENCY}`);
    } else if (command === "done") {
      break;
    }
  } catch (err) {
    console.log(`error: ${err.message}`);
  }
}

