export const CURRENCY = "EUR";

export function parseCents(text) {
  if (!text || ![...text].every(ch => ch >= "0" && ch <= "9")) throw new Error("bad price");
  return Number(text);
}

export function formatCents(cents) {
  return (cents / 100).toFixed(2);
}

solution.cart.js:
export default class Cart {
  #items = new Map();

  add(name, cents, qty) {
    const item = this.#items.get(name);
    if (item) item.qty += qty;
    else this.#items.set(name, { cents, qty });
  }

  remove(name) {
    return this.#items.delete(name);
  }

  get total() {
    let sum = 0;
    for (const { cents, qty } of this.#items.values()) sum += cents * qty;
    return sum;
  }
}
